"""matplotlib.quiver — quiver and barbs plot stubs."""

from matplotlib.artist import Artist
import numpy as _np


class QuiverKey(Artist):
    def __init__(self, Q, X, Y, U, label, **kwargs):
        super().__init__()
        self.Q = Q
        self.X = X
        self.Y = Y
        self.U = U
        self.label = label


class Quiver(Artist):
    """Vector-field arrow plot. Stores X/Y/U/V/C arrays so callers can
    inspect them; plotly's quiver trace handles the actual drawing."""

    def __init__(self, ax, *args, scale=None, scale_units=None, units='width',
                 angles='uv', width=None, headwidth=3, headlength=5,
                 headaxislength=4.5, minshaft=1, minlength=1, pivot='tail',
                 color=None, **kwargs):
        super().__init__()
        self.ax = ax
        # Upstream's signature: Quiver(ax, X, Y, U, V, C) — store whichever
        # subset was given.
        self.X = self.Y = self.U = self.V = self.C = None
        if len(args) >= 2:
            self.U = _np.asarray(args[-2 if len(args) == 4 or len(args) == 5 else -2])
            self.V = _np.asarray(args[-1 if len(args) == 4 or len(args) == 5 else -1])
        if len(args) >= 4:
            self.X = _np.asarray(args[0])
            self.Y = _np.asarray(args[1])
            self.U = _np.asarray(args[2])
            self.V = _np.asarray(args[3])
        if len(args) == 5:
            self.C = _np.asarray(args[4])
        self.scale = scale
        self.scale_units = scale_units
        self.units = units
        self.angles = angles
        self.width = width
        self.headwidth = headwidth
        self.headlength = headlength
        self.headaxislength = headaxislength
        self.minshaft = minshaft
        self.minlength = minlength
        self.pivot = pivot
        self.color = color

    def set_UVC(self, U, V, C=None):
        self.U = _np.asarray(U)
        self.V = _np.asarray(V)
        if C is not None:
            self.C = _np.asarray(C)

    def set_offsets(self, offsets):
        offsets = _np.asarray(offsets)
        if offsets.ndim == 2 and offsets.shape[1] == 2:
            self.X = offsets[:, 0]
            self.Y = offsets[:, 1]
        self._offsets = offsets

    def get_offsets(self):
        if hasattr(self, '_offsets'):
            return self._offsets
        if self.X is not None and self.Y is not None:
            return _np.column_stack([self.X.ravel(), self.Y.ravel()])
        return _np.empty((0, 2))

    def get_datalim(self, transData):
        """Bbox covering both arrow tails and tips."""
        from matplotlib.transforms import Bbox
        if self.X is None or self.Y is None:
            return Bbox.from_extents(0, 0, 1, 1)
        xs = self.X.ravel(); ys = self.Y.ravel()
        if self.U is not None and self.V is not None:
            # Include arrow tips (X+U, Y+V) so axis autoscale captures them.
            us = (self.U.ravel() if hasattr(self.U, 'ravel') else _np.atleast_1d(self.U))
            vs = (self.V.ravel() if hasattr(self.V, 'ravel') else _np.atleast_1d(self.V))
            # Apply quiver scale if provided.
            scale = self.scale or 1.0
            x_all = _np.concatenate([xs, xs + us / scale])
            y_all = _np.concatenate([ys, ys + vs / scale])
        else:
            x_all, y_all = xs, ys
        return Bbox.from_extents(float(x_all.min()), float(y_all.min()),
                                  float(x_all.max()), float(y_all.max()))


class Barbs(Artist):
    """Wind-barb plot (meteorology-style)."""

    def __init__(self, ax, *args, length=7, pivot='tip', barbcolor=None,
                 flagcolor=None, sizes=None, fill_empty=False, rounding=True,
                 barb_increments=None, flip_barb=False, **kwargs):
        super().__init__()
        self.ax = ax
        self.X = self.Y = self.U = self.V = self.C = None
        if len(args) >= 4:
            self.X = _np.asarray(args[0])
            self.Y = _np.asarray(args[1])
            self.U = _np.asarray(args[2])
            self.V = _np.asarray(args[3])
        if len(args) == 5:
            self.C = _np.asarray(args[4])
        self.length = length
        self.pivot = pivot
        self.barbcolor = barbcolor
        self.flagcolor = flagcolor
        self.sizes = sizes or {}
        self.fill_empty = fill_empty
        self.rounding = rounding
        self.barb_increments = barb_increments or {}
        self.flip_barb = flip_barb

    def set_UVC(self, U, V, C=None):
        self.U = _np.asarray(U)
        self.V = _np.asarray(V)
        if C is not None:
            self.C = _np.asarray(C)

    def set_offsets(self, offsets):
        offsets = _np.asarray(offsets)
        if offsets.ndim == 2 and offsets.shape[1] == 2:
            self.X = offsets[:, 0]
            self.Y = offsets[:, 1]
        self._offsets = offsets

    def get_offsets(self):
        if hasattr(self, '_offsets'):
            return self._offsets
        if self.X is not None and self.Y is not None:
            return _np.column_stack([self.X.ravel(), self.Y.ravel()])
        return _np.empty((0, 2))


